(()=>{
 const key='bicolang-trials-v1';let records=[];try{records=JSON.parse(localStorage.getItem(key)||'[]');if(!Array.isArray(records))records=[];}catch{}
 function add(record){const {start,audioStart,id,...fields}=record;records.push({...fields,timestamp:new Date().toISOString(),userAgent:navigator.userAgent});records=records.slice(-500);try{localStorage.setItem(key,JSON.stringify(records));}catch{}globalThis.dispatchEvent(new Event('bicolang-trials'));render();}
 function clear(){records=[];try{localStorage.removeItem(key);}catch{}globalThis.dispatchEvent(new Event('bicolang-trials'));render();}
 function render(){const target=document.getElementById('timingCards');if(!target)return;target.replaceChildren();for(const kind of ['Translation','STT','TTS']){const successful=records.filter(r=>r.kind===kind&&['exact','fuzzy','completed'].includes(r.outcome)&&Number.isFinite(r.ms));const card=document.createElement('div'),title=document.createElement('strong'),value=document.createElement('span'),detail=document.createElement('small');title.textContent=kind;value.textContent=successful.length?(successful.at(-1).ms/1000).toFixed(3)+' s':'—';detail.textContent=successful.length?`Mean ${(successful.reduce((s,r)=>s+r.ms,0)/successful.length/1000).toFixed(3)} s · ${successful.length} successful trials`:'Run a trial to measure';card.append(title,value,detail);target.append(card);}}
 function csv(){const columns=['timestamp','kind','language','model','query','outcome','ms','postSpeechMs','durationMs','expected','detected','correct','semitones','voicedFrames','userAgent'];const cell=v=>'"'+String(v??'').replace(/"/g,'""').replace(/^[=+@-]/,"'$&")+'"';return columns.join(',')+'\n'+records.map(r=>columns.map(k=>cell(r[k])).join(',')).join('\n');}
 globalThis.BICOLANGMeasurements={add,clear,list:()=>records.map(r=>({...r})),csv};render();
})();
